css:
.sl-article-course {
    background-color: var(--smartlearn-bg);
    padding-block: 3rem;
}
@media (min-width: 992px) {
    .sl-article-course { padding-block: 6rem; }
}

.sl-article-course .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-course .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-course .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-course .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-course .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-course .sl-badge-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, transparent);
}
.sl-article-course .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-course .sl-tracking-wide { letter-spacing: 0.1em; }

.sl-article-course .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

.sl-article-course .sl-sticky-media {
    position: sticky;
    top: calc(var(--smartlearn-navbar-height, 64px) + 1.5rem);
}

.sl-article-course .sl-btn-cta {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    transition: background-color 0.2s ease, transform 0.2s ease;
}
.sl-article-course .sl-btn-cta:hover,
.sl-article-course .sl-btn-cta:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}

.sl-article-course .sl-outcome-card {
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-article-course .sl-outcome-card:hover {
        transform: translateY(-3px);
        box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.08);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-article-course .sl-outcome-card,
    .sl-article-course .sl-btn-cta { transition: none; }
}
